CREATE TABLE tbl_appinfo_page(pageId INTEGER PRIMARY KEY NOT NULL ,pageNo INT NOT NULL,themeFile TEXT,bgColor INT,texWidth INT,texHeight INT,imageWidth INT,imageHeight INT,reserved01,reserved02,reserved03,reserved04,reserved05);
CREATE TABLE tbl_appinfo_icon(pageId REFERENCES tbl_appinfo_page(pageId) ON DELETE RESTRICT NOT NULL,pos INT NOT NULL,iconPath TEXT,title TEXT COLLATE NOCASE,type NOT NULL,command TEXT, titleId TEXT,icon0Type NOT NULL,parentalLockLv INT,status INT,reserved01,reserved02,reserved03,reserved04,reserved05,PRIMARY KEY(pageId, pos));
CREATE TABLE tbl_appinfo(titleId TEXT NOT NULL,key INTEGER NOT NULL,val,PRIMARY KEY(titleId, key));
CREATE TABLE tbl_config (ikey INTEGER PRIMARY KEY NOT NULL ,val);
CREATE INDEX idx_page_no ON tbl_appinfo_page ( pageNo );
CREATE INDEX idx_icon_pos ON tbl_appinfo_icon ( pos, pageId );
CREATE INDEX idx_icon_title ON tbl_appinfo_icon (title, titleId, type);
CREATE TABLE tbl_uri(titleId TEXT NOT NULL,flag INT,scheme TEXT NOT NULL,hostpath TEXT);
CREATE INDEX id_scheme ON tbl_uri (scheme);
CREATE TRIGGER tgr_deletePage2 AFTER DELETE ON tbl_appinfo_page WHEN OLD.pageNo >= 0 BEGIN UPDATE tbl_appinfo_page SET pageNo=pageNo-1 WHERE tbl_appinfo_page.pageNo>OLD.pageNo; END;
CREATE TRIGGER tgr_insertPage2 BEFORE INSERT ON tbl_appinfo_page WHEN NEW.pageNo >= 0 BEGIN UPDATE tbl_appinfo_page SET pageNo=pageNo+1 WHERE tbl_appinfo_page.pageNo>=NEW.pageNo; END;
CREATE TABLE tbl_theme(id TEXT PRIMARY KEY NOT NULL,packageImageFilePath TEXT,homePreviewFilePath TEXT,startPreviewFilePath TEXT,contentVer INTEGER,lastModifiedTime TEXT,size INTEGER,type INTEGER,titleDefault BLOB,providerDefault BLOB,title0 BLOB,provider0 BLOB,title1 BLOB,provider1 BLOB,title2 BLOB,provider2 BLOB,title3 BLOB,provider3 BLOB,title4 BLOB,provider4 BLOB,title5 BLOB,provider5 BLOB,title6 BLOB,provider6 BLOB,title7 BLOB,provider7 BLOB,title8 BLOB,provider8 BLOB,title9 BLOB,provider9 BLOB,title10 BLOB,provider10 BLOB,title11 BLOB,provider11 BLOB,title12 BLOB,provider12 BLOB,title13 BLOB,provider13 BLOB,title14 BLOB,provider14 BLOB,title15 BLOB,provider15 BLOB,title16 BLOB,provider16 BLOB,title17 BLOB,provider17 BLOB,title18 BLOB,provider18 BLOB,title19 BLOB,provider19 BLOB,title20 BLOB,provider20 BLOB,title21 BLOB,provider21 BLOB,title22 BLOB,provider22 BLOB,title23 BLOB,provider23 BLOB,title24 BLOB,provider24 BLOB,title25 BLOB,provider25 BLOB,reserved01,reserved02,reserved03,reserved04,reserved05);
CREATE INDEX idx_theme_time ON tbl_theme(lastModifiedTime);
CREATE TABLE tbl_livearea (titleId TEXT PRIMARY KEY,org_path TEXT NOT NULL,style TEXT NOT NULL,formatVer TEXT NOT NULL,contentRev INT,background_image TEXT,gate_startupImage TEXT,titleColor INT,modifiedDate TEXT,sfType0 INT,sfTarg0 TEXT,sfType1 INT,sfTarg1 TEXT,sfType2 INT,sfTarg2 TEXT,sfType3 INT,sfTarg3 TEXT,sfType4 INT,sfTarg4 TEXT,sfType5 INT,sfTarg5 TEXT,sfType6 INT,sfTarg6 TEXT,sfType7 INT,sfTarg7 TEXT, pccUpdDate INT, pccResStatus INT, pccSignOff INT);
CREATE TABLE tbl_livearea_frame(titleId TEXT NOT NULL,frameId TEXT NOT NULL,type INT NOT NULL,frameMulti INT,frameAutoFlip INT,frameRev INT,item0_xml TEXT,item0_bg_path TEXT,item0_img_path TEXT,item1_xml TEXT,item1_bg_path TEXT,item1_img_path TEXT,item2_xml TEXT,item2_bg_path TEXT,item2_img_path TEXT,item3_xml TEXT,item3_bg_path TEXT,item3_img_path TEXT,item4_xml TEXT,item4_bg_path TEXT,item4_img_path TEXT,item5_xml TEXT,item5_bg_path TEXT,item5_img_path TEXT,item6_xml TEXT,item6_bg_path TEXT,item6_img_path TEXT,item7_xml TEXT,item7_bg_path TEXT,item7_img_path TEXT,item8_xml TEXT,item8_bg_path TEXT,item8_img_path TEXT,item9_xml TEXT,item9_bg_path TEXT,item9_img_path TEXT,userdata TEXT,PRIMARY KEY (titleId, frameId, type),FOREIGN KEY (titleId) REFERENCES tbl_livearea(titleId) ON DELETE CASCADE);
CREATE TABLE tbl_livearea_file (rowid INTEGER PRIMARY KEY AUTOINCREMENT,refcnt INT  NOT NULL,ext TEXT NOT NULL,dir TEXT NOT NULL);
CREATE TRIGGER tgr_livearea_file_update AFTER UPDATE OF refcnt ON tbl_livearea_file WHEN NEW.refcnt = 0 BEGIN DELETE FROM tbl_livearea_file WHERE rowid=NEW.rowid; END;
CREATE TRIGGER tgr_livearea_file_delete BEFORE DELETE ON tbl_livearea_file BEGIN SELECT add_rm_list(dir||'/'||' '||rowid||ext) FROM tbl_livearea_file WHERE rowid=OLD.rowid;END;
CREATE TRIGGER tgr_livearea_upd_bgimg AFTER UPDATE OF background_image ON tbl_livearea WHEN OLD.background_image LIKE ' %' BEGIN UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.background_image AS INTEGER);END;
CREATE TRIGGER tgr_livearea_upd_gtimg AFTER UPDATE OF gate_startupImage ON tbl_livearea WHEN OLD.gate_startupImage LIKE ' %' BEGIN UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.gate_startupImage AS INTEGER);END;
CREATE TRIGGER tgr_livearea_del_img AFTER DELETE ON tbl_livearea WHEN OLD.gate_startupImage LIKE ' %' OR OLD.background_image LIKE ' %' BEGIN UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.gate_startupImage AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.background_image AS INTEGER);END;
CREATE TRIGGER tgr_livearea_frame_del_item BEFORE DELETE ON tbl_livearea_frame WHEN OLD.item0_bg_path LIKE ' %' OR OLD.item0_img_path LIKE ' %' OR OLD.item1_bg_path LIKE ' %' OR OLD.item1_img_path LIKE ' %' OR OLD.item2_bg_path LIKE ' %' OR OLD.item2_img_path LIKE ' %' OR OLD.item3_bg_path LIKE ' %' OR OLD.item3_img_path LIKE ' %' OR OLD.item4_bg_path LIKE ' %' OR OLD.item4_img_path LIKE ' %' OR OLD.item5_bg_path LIKE ' %' OR OLD.item5_img_path LIKE ' %' OR OLD.item6_bg_path LIKE ' %' OR OLD.item6_img_path LIKE ' %' OR OLD.item7_bg_path LIKE ' %' OR OLD.item7_img_path LIKE ' %' OR OLD.item8_bg_path LIKE ' %' OR OLD.item8_img_path LIKE ' %' OR OLD.item9_bg_path LIKE ' %' OR OLD.item9_img_path LIKE ' %' BEGIN UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item0_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item0_img_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item1_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item1_img_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item2_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item2_img_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item3_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item3_img_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item4_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item4_img_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item5_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item5_img_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item6_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item6_img_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item7_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item7_img_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item8_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item8_img_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item9_bg_path AS INTEGER);UPDATE tbl_livearea_file SET refcnt=refcnt-1 WHERE rowid=CAST(OLD.item9_img_path AS INTEGER);END;
CREATE TABLE tbl_newevent (rowid INTEGER PRIMARY KEY AUTOINCREMENT,id_title_id TEXT NOT NULL,id_item_id TEXT NOT NULL,del_flag INT NOT NULL,msg_type INT NOT NULL,act_type INT NOT NULL,time_updated DEFAULT CURRENT_TIMESTAMP,new_flag INT,popup_no INT,icon_path TEXT,exec_mode INT NOT NULL,exec_title_id TEXT,exec_arg TEXT,title TEXT,desc TEXT,msg_arg0 TEXT, msg_arg1 TEXT, msg_arg2 TEXT,msg_arg3 TEXT, msg_arg4 TEXT, msg_arg5 TEXT,msg_arg6 TEXT, msg_arg7 TEXT, msg_arg8 TEXT,se_id INT,se_volume REAL,hash INT DEFAULT 1 NOT NULL,icon_data BLOB);
CREATE TRIGGER tgr_newevent_popup_ins AFTER INSERT ON tbl_newevent WHEN 0<NEW.popup_no BEGIN SELECT increment_popup_num();END;
CREATE TRIGGER tgr_newevent_popup_upins BEFORE UPDATE OF popup_no ON tbl_newevent WHEN OLD.popup_no=0 AND 0<NEW.popup_no BEGIN SELECT increment_popup_num();END;
CREATE TRIGGER tgr_newevent_popup_updel BEFORE UPDATE OF popup_no ON tbl_newevent WHEN 0<OLD.popup_no AND NEW.popup_no=0 BEGIN SELECT decrement_popup_num();END;
CREATE TRIGGER tgr_newevent_autoDel AFTER UPDATE ON tbl_newevent WHEN NEW.popup_no=0 AND 1=NEW.del_flag BEGIN DELETE FROM tbl_newevent WHERE ROWID=NEW.ROWID;END;
